        expect(at(1.1, () => shows(flow.cursor))).toBeLessThan(1)
        expect(at(1.3, () => shows(flow.cursor))).toBe(1)
        expect(at(1.1, () => shows(first!.shape))).toBeGreaterThan(0)
        expect(at(1.1, () => shows(first!.text!))).toBe(0)
